// Sheet mode only. The Google Sheets node emits one item per row plus a
// row_number field; keep the FIRST row whose Status column is empty so the
// update node at the end can mark exactly that row as done.
const rows = $input.all().map((i) => i.json);
const isEmpty = (v) => v === undefined || v === null || String(v).trim() === '';
const row = rows.find((r) => isEmpty(r.Status));

if (!row) {
  return [{ json: { found: false, checked: rows.length, reason: 'No row with an empty Status column. Add product rows to the sheet.' } }];
}
if (isEmpty(row.Title)) {
  throw new Error('Row ' + row.row_number + ' has no Title. Fill it in, or put anything in its Status column to skip the row.');
}
if (isEmpty(row.ImageUrl1)) {
  throw new Error('Row ' + row.row_number + ' has no ImageUrl1. Every product needs at least one public image URL (a Shopify CDN link works).');
}

return [{ json: { found: true, row, rowNumber: row.row_number, checked: rows.length } }];

// Normalizes BOTH sources to one product shape, so everything downstream —
// the builder, the render chain, the summary — is source-agnostic:
//
//   { found, title, price, compareAtPrice, imageUrls[], tagline,
//     rowNumber?, productId?, source }
//
// Shopify mode also de-duplicates: the newest product is compared against the
// last one this workflow announced (kept in the workflow's static data). The
// FIRST shopify run only seeds that marker — it never floods the channel with
// a back catalogue.
const cfg = $('Config').first().json;
const source = String(cfg.source || 'sheet').trim().toLowerCase();
const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
const fallbackTagline = clean(cfg.fallbackTagline) || 'Just landed — available now.';
const maxTagline = Number(cfg.maxTaglineChars) > 20 ? Number(cfg.maxTaglineChars) : 90;

// Trims to a word boundary and adds an ellipsis, so a full product description
// never runs off the design.
const trimTo = (text, max) => {
  const s = clean(text);
  if (s.length <= max) return s;
  const cut = s.slice(0, max - 1);
  const at = cut.lastIndexOf(' ');
  let out = (at > max * 0.5 ? cut.slice(0, at) : cut).replace(/[\s,;:.—-]+$/, '');
  // "…talc-free and kind to…" reads badly; drop a dangling article or
  // preposition so the ellipsis lands on a word that carries meaning.
  out = out.replace(/\s+(a|an|and|as|at|but|by|for|from|in|into|of|on|or|the|to|with)$/i, '');
  return out.replace(/[\s,;:.—-]+$/, '') + '…';
};

if (source === 'sheet') {
  const picked = $input.first().json;
  if (!picked || picked.found !== true) {
    return [{ json: { found: false, source: 'sheet', checked: (picked && picked.checked) || 0, reason: (picked && picked.reason) || 'No product row waiting.' } }];
  }
  const row = picked.row || {};
  const imageUrls = [clean(row.ImageUrl1), clean(row.ImageUrl2)].filter((u) => /^https?:\/\//i.test(u));
  if (!imageUrls.length) {
    throw new Error('Row ' + picked.rowNumber + ': ImageUrl1 is not a public http(s) URL.');
  }
  return [{
    json: {
      found: true,
      source: 'sheet',
      title: clean(row.Title),
      price: clean(row.Price),
      compareAtPrice: clean(row.CompareAtPrice),
      tagline: trimTo(row.Tagline, maxTagline) || fallbackTagline,
      imageUrls,
      rowNumber: picked.rowNumber,
      productId: null,
      checked: picked.checked,
    },
  }];
}

// ---- Shopify mode ---------------------------------------------------------
const res = $input.first().json || {};
const status = Number(res.statusCode);
const body = res.body === undefined ? res : res.body;

// `Poll new products` is deliberately non-fatal (alwaysOutputData +
// continueRegularOutput + neverError) so a Shopify hiccup never red-flags a
// scheduled run mid-flight. That also means a DNS/connection failure — an empty
// or mistyped shopDomain, a shop that is down — arrives here as an item with NO
// status code at all. Reporting that as "your shop has no products" would leave
// a broken install looking green forever, so it is an error with the fix in it.
if (!Number.isFinite(status) || status <= 0) {
  const raw = res.error;
  const detail = clean(typeof raw === 'string' ? raw : (raw && (raw.message || raw.description)) || res.message);
  const shop = clean(cfg.shopDomain);
  throw new Error(
    'Could not reach the Shopify Admin API at https://' + (shop || '<shopDomain is empty>') + '.myshopify.com — no HTTP response came back'
    + (detail ? ' (' + detail + ')' : '') + '. Check that shopDomain in Config is just the subdomain (my-shop, not my-shop.myshopify.com) and that the shop is reachable.'
  );
}

if (status !== 200) {
  const hint = status === 401 || status === 403
    ? 'The X-Shopify-Access-Token credential was rejected. Re-check the custom app token (it starts with shpat_) and that the app has read_products.'
    : status === 404
      ? 'That admin API path does not exist on this shop. Check shopDomain (just the my-shop part) and apiVersion in Config.'
      : status === 429
        ? 'Shopify is rate-limiting the admin API. The schedule polls every 30 minutes, which never hits the limit on its own — if you lowered the interval or another workflow shares this token, raise the interval again. Nothing was lost; the next poll picks the product up.'
        : 'Shopify returned an error.';
  throw new Error('Shopify products poll failed (HTTP ' + status + '). ' + hint);
}

const products = body && Array.isArray(body.products) ? body.products : [];
if (!products.length) {
  return [{ json: { found: false, source: 'shopify', checked: 0, reason: 'The shop returned no products. Nothing to announce.' } }];
}

const store = $getWorkflowStaticData('global');
const newest = products[0];
const newestId = String(newest.id);

if (!store.lastProductId) {
  store.lastProductId = newestId;
  return [{
    json: {
      found: false,
      source: 'shopify',
      checked: products.length,
      seeded: true,
      reason: 'First Shopify run: remembered "' + clean(newest.title) + '" as the latest product. The next product you publish gets a video.',
    },
  }];
}

if (String(store.lastProductId) === newestId) {
  return [{ json: { found: false, source: 'shopify', checked: products.length, reason: 'No product newer than the last one announced.' } }];
}

const variant = (Array.isArray(newest.variants) ? newest.variants : [])[0] || {};
const imageUrls = (Array.isArray(newest.images) ? newest.images : [])
  .map((im) => clean(im && im.src))
  .filter((u) => /^https?:\/\//i.test(u))
  .slice(0, 2);
if (!imageUrls.length && newest.image && clean(newest.image.src)) imageUrls.push(clean(newest.image.src));
if (!imageUrls.length) {
  throw new Error('Product "' + clean(newest.title) + '" has no image in the Shopify API response. Add a product photo and publish it again.');
}

// body_html is real HTML — strip tags and decode the entities Shopify emits
// before any of it reaches the design.
const plain = String(newest.body_html || '')
  .replace(/<br\s*\/?>/gi, ' ')
  .replace(/<\/(p|div|li|h[1-6])>/gi, ' ')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  // Stripping tags leaves gaps in front of punctuation ("matte , satin").
  .replace(/\s+([,.;:!?%])/g, '$1')
  .trim();

return [{
  json: {
    found: true,
    source: 'shopify',
    title: clean(newest.title),
    price: clean(variant.price),
    compareAtPrice: clean(variant.compare_at_price),
    tagline: trimTo(plain, maxTagline) || fallbackTagline,
    imageUrls,
    rowNumber: null,
    productId: newestId,
    handle: clean(newest.handle),
    checked: products.length,
  },
}];

// Nothing is waiting. This is a normal, successful outcome - not an error, so
// the scheduled run stays green and simply reports why it did nothing.
const picked = $input.first().json;
return [{
  json: {
    rendered: false,
    source: picked.source,
    reason: picked.reason || 'Nothing to render.',
    productsChecked: picked.checked,
    seededShopifyMarker: picked.seeded === true,
  },
}];

// === buildProject — identical to the frame-reviewed standalone builder ===
// One product (from the sheet or from the Shopify products poll) becomes a
// three-scene 1080x1920 promo: hook / offer / call to action.
//
// Product photography is the one thing this template must never damage, so
// every product image is placed with resize:'contain' inside a designed plate.
// Nothing is ever cropped, whatever aspect ratio the store uploads.
function buildProject(config, product, probe) {
  const cfg = config || {};
  const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const round2 = (n) => Math.round(n * 100) / 100;

  // ---- colour helpers -----------------------------------------------------
  const hexToRgb = (hex) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(clean(hex));
    if (!m) return null;
    const n = parseInt(m[1], 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  };
  const rgba = (hex, a, fallback) => {
    const c = hexToRgb(hex) || fallback || [20, 26, 32];
    return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
  };
  const lighten = (hex, amt) => {
    const c = hexToRgb(hex) || [20, 26, 32];
    const h = (v) => ('0' + Math.min(255, Math.max(0, v + amt)).toString(16)).slice(-2);
    return '#' + h(c[0]) + h(c[1]) + h(c[2]);
  };
  // Relative luminance + WCAG contrast, so the design stays legible whatever
  // colours the store puts in Config.
  const luminance = (hex) => {
    const c = hexToRgb(hex) || [0, 0, 0];
    const lin = c.map((v) => {
      const s = v / 255;
      return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    });
    return 0.2126 * lin[0] + 0.7152 * lin[1] + 0.0722 * lin[2];
  };
  const contrast = (a, b) => {
    const la = luminance(a);
    const lb = luminance(b);
    return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
  };

  // ---- brand knobs --------------------------------------------------------
  const ink = /^#?[0-9a-f]{6}$/i.test(clean(cfg.brandColor)) ? clean(cfg.brandColor) : '#141A20';
  const accent = /^#?[0-9a-f]{6}$/i.test(clean(cfg.brandAccent)) ? clean(cfg.brandAccent) : '#E1623C';
  const CREAM = '#F6F2EA'; // fixed paper tone the whole system is built on
  const CREAM_RGB = [246, 242, 234];
  // Label colour for anything sitting ON the accent (chips, badge, button,
  // monogram): whichever of the brand ink / paper / plain black / plain white
  // contrasts most. Picking the best of those is never worse than 4:1, so a
  // pale yellow accent gets dark labels and a deep navy accent gets light ones
  // without anyone having to think about it.
  const onAccent = [ink, CREAM, '#111111', '#FFFFFF']
    .map((c) => ({ c, r: contrast(c, accent) }))
    .sort((a, b) => b.r - a.r)[0].c;
  // Accent used as TEXT on the dark base: nudged towards the light until it
  // clears 3.5:1, so a very dark brand accent is still readable on ink.
  const readableAccent = (() => {
    let c = hexToRgb(accent) || [225, 98, 60];
    const hex2 = (v) => ('0' + Math.max(0, Math.min(255, Math.round(v))).toString(16)).slice(-2);
    const goLighter = luminance(ink) < 0.35;
    for (let i = 0; i < 14; i += 1) {
      const cur = '#' + hex2(c[0]) + hex2(c[1]) + hex2(c[2]);
      if (contrast(cur, ink) >= 3.5) return cur;
      c = c.map((v) => (goLighter ? v + (255 - v) * 0.18 : v * 0.82));
    }
    return goLighter ? '#FFFFFF' : '#111111';
  })();
  const titleFont = clean(cfg.titleFont) || 'Fraunces';
  const uiFont = clean(cfg.uiFont) || 'Archivo';
  const brandName = clean(cfg.brandName) || 'Your store';
  const brandHandle = clean(cfg.brandHandle);
  const shopNowText = clean(cfg.shopNowText) || 'Shop now';
  const kicker = (clean(cfg.newArrivalKicker) || 'NEW ARRIVAL').toUpperCase();

  // storeUrl may be a full URL or a bare domain — the video only ever shows
  // the host, never a protocol or a tracking query string.
  const storeDomain = clean(cfg.storeUrl)
    .replace(/^[a-z]+:\/\//i, '')
    .replace(/^www\./i, '')
    .split(/[/?#]/)[0]
    .toLowerCase();

  // ---- product ------------------------------------------------------------
  const title = clean(product && product.title);
  if (!title) throw new Error('The product has no title — nothing to put on screen.');
  const tagline = clean(product && product.tagline);
  const images = (Array.isArray(product && product.imageUrls) ? product.imageUrls : [])
    .map(clean)
    .filter((u) => /^https?:\/\//i.test(u));
  if (!images.length) throw new Error('The product has no usable image URL. Product images must be public https URLs (Shopify CDN links are).');
  const heroImage = images[0];
  // A second angle is a nicer second scene, but one photo is the common case:
  // the offer scene then re-frames the same shot — a different plate, and a
  // drift that moves the opposite way on both axes (see `drawBack` below).
  const offerImage = images[1] || images[0];
  const imageReused = !images[1];

  // ---- price / saving -----------------------------------------------------
  // Sheets carry "$189.00" or "189"; the Shopify API carries "189.00". Keep a
  // symbol the merchant typed, add the configured one when there is none.
  const symbol = clean(cfg.currencySymbol) || '$';
  const parseMoney = (raw) => {
    const digits = clean(raw).replace(/[^0-9.,]/g, '').replace(/,(?=\d{3}\b)/g, '');
    const n = Number(digits.replace(/,/g, '.'));
    return Number.isFinite(n) && n > 0 ? n : 0;
  };
  const displayMoney = (raw) => {
    const s = clean(raw);
    if (!s) return '';
    return /[0-9]/.test(s) && !/[^\d.,\s]/.test(s) ? symbol + s : s;
  };
  const priceValue = parseMoney(product && product.price);
  const compareValue = parseMoney(product && product.compareAtPrice);
  const priceText = displayMoney(product && product.price);
  const compareText = compareValue > priceValue ? displayMoney(product && product.compareAtPrice) : '';
  const savePct = compareText && priceValue > 0 ? Math.round((1 - priceValue / compareValue) * 100) : 0;
  const showSave = savePct >= 1 && savePct <= 95;

  // ---- music guard --------------------------------------------------------
  // `probe` is the full HEAD response for cfg.musicUrl. An unreachable or
  // oversized bed is dropped, never fatal — the promo still renders.
  const musicUrl = clean(cfg.musicUrl);
  const limit = Number(cfg.maxMusicBytes) > 0 ? Number(cfg.maxMusicBytes) : 5242880;
  const headers = (probe && probe.headers) || {};
  const musicBytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
  const musicOk = !!musicUrl && Number(probe && probe.statusCode) === 200 && (!musicBytes || musicBytes <= limit);
  const musicSkipped = musicOk
    ? null
    : (!musicUrl ? 'musicUrl empty' : (Number(probe && probe.statusCode) !== 200 ? 'HEAD ' + ((probe && probe.statusCode) || 'failed') : musicBytes + ' bytes > ' + limit));

  // ---- adaptive type ------------------------------------------------------
  // Greedy word-wrap estimate calibrated on the rendered design sources:
  // Fraunces 700 mixed-case runs ~0.52 em per character, Archivo 500 ~0.50 em.
  const wrapLines = (text, fontPx, boxPx, avgEm) => {
    const perLine = Math.max(5, Math.floor(boxPx / (fontPx * avgEm)));
    let n = 1;
    let used = 0;
    for (const w of String(text).split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      n += 1;
      used = Math.min(w.length, perLine);
    }
    return n;
  };
  // Steps down through a size ladder until the copy fits in `maxLines`, so a
  // 70-character product name never pushes the block into the footer. When even
  // the smallest step still overflows — Shopify allows a 255-character product
  // title and a sheet cell is unbounded — the copy itself is trimmed on a word
  // boundary and marked with an ellipsis. The block can then never grow past
  // `maxLines`, so nothing below it is ever pushed off the 1920 px canvas.
  const fitBlock = (text, sizes, boxPx, avgEm, maxLines) => {
    const src = String(text);
    for (const size of sizes) {
      const lines = wrapLines(src, size, boxPx, avgEm);
      if (lines <= maxLines) return { size, lines, text: src, truncated: false };
    }
    const size = sizes[sizes.length - 1];
    const perLine = Math.max(5, Math.floor(boxPx / (size * avgEm)));
    const budget = Math.max(4, perLine * maxLines - 1); // one char of room for the ellipsis
    let cut = src.slice(0, budget);
    const at = cut.lastIndexOf(' ');
    if (at > budget * 0.5) cut = cut.slice(0, at);
    let out = cut.replace(/[\s,;:.—-]+$/, '') + '…';
    while (wrapLines(out, size, boxPx, avgEm) > maxLines && out.length > 3) {
      out = out.slice(0, -2).replace(/[\s,;:.—-]+$/, '') + '…';
    }
    return { size, lines: wrapLines(out, size, boxPx, avgEm), text: out, truncated: true };
  };

  const titleFit = fitBlock(title, [92, 80, 68, 58, 50, 44], 900, 0.52, 3);
  const taglineFit = tagline
    ? fitBlock(tagline, [46, 40, 35, 31], 900, 0.5, 3)
    : { size: 0, lines: 0, text: '', truncated: false };
  // A one-line block can rise into place; a paragraph must not, because the
  // masked rise uncovers its LAST line first and the sentence reads bottom-up
  // for a third of a second. Multi-line copy fades in as one block.
  const reveal = (fit) => (fit.lines > 1 ? 'fade' : 'smoothup');

  // ---- product photo layer ------------------------------------------------
  // A store's photos arrive in every aspect ratio there is (square, 4:5, 2:3,
  // wide lifestyle shots) and cropping one is how an automation ruins a
  // product page. This places the photo as an IMAGE LAYER inside a fixed
  // plate: `object-fit: contain` fits the whole shot in the box, centred,
  // never cropped and never stretched — the box, not the photo, decides the
  // composition. (The element-level `resize: 'contain'` field is a different
  // thing: it fits the media to the whole 1080x1920 canvas.)
  // `max-width`/`max-height` (not width/height) keep the browser's own
  // aspect-preserving fit, and leaving the element unsized makes the rendered
  // layer exactly the size of the fitted photo — so `anchor: center-center`
  // centres the PHOTO in the plate, with no transparent letterbox padding.
  //
  // `edge` is a hairline drawn on the span that WRAPS the photo, so it lands
  // exactly on the fitted photo's real edge whatever aspect ratio the store
  // uploaded. It is the tone the plate is NOT, so the photo still reads as a
  // mounted print in the two cases where the plate would otherwise swallow it:
  // a white studio cut-out on the cream plate, and a dark lifestyle shot on the
  // dark card.
  //
  // The photo also MOVES. `.kbox` is the plate's photo box (fixed w x h,
  // overflow hidden); the photo lives inside it and is animated by customCode:
  // an entrance, then a slow continuous drift for the rest of the scene. Every
  // keyframe keeps the scale at or below 1, and the box is what the photo is
  // measured against — so the whole product is on screen the entire time and
  // the drift can never crop it. The two scenes drift in DIFFERENT directions
  // (scene 1 rises and pushes in, scene 2 slides across and pulls back), which
  // is what re-frames the shot when a product has only one photo.
  //
  // customCode captures ONE loop and repeats it, so `animationDuration` is the
  // element's full on-screen length and the loop never restarts mid-scene.
  // The element itself stays UNSIZED: `.kbox` carries the box, so the rendered
  // layer measures exactly w x h from its content. (Declaring width/height on
  // the element instead makes the layout linter treat the photo as a sized
  // region overlapping the full-canvas backdrop and warn about it.)
  const photoLayer = (src, cx, cy, w, h, track, textColor, edge, motion) => ({
    type: 'TEXT',
    x: cx,
    y: cy,
    anchor: 'center-center',
    track,
    enterBegin: 0,
    exitEnd: motion.seconds,
    style: { fontFamily: uiFont, color: textColor },
    customCode: {
      animationDuration: motion.seconds,
      css:
        '.kbox{width:' + w + 'px; height:' + h + 'px; display:flex; align-items:center; justify-content:center; overflow:hidden}' +
        '.kbi{display:inline-block; line-height:0; border:1px solid ' + edge + '; animation:' + motion.name + ' ' + motion.seconds + 's linear 1 both}' +
        motion.keyframes,
    },
    html:
      "<div class='kbox'><span class='kbi'><img src='" + esc(src) +
      "' alt='' style='max-width:" + (w - 2) + 'px; max-height:' + (h - 2) + "px; display:block;'/></span></div>",
  });

  // Rise + push in (scene 1). Slack check: at scale 0.86 a box-filling photo
  // leaves 7% of the box free on each side, which is more than the 46 px it is
  // lifted by, so even the entrance frame is fully inside the box.
  const EASE = 'cubic-bezier(0.22,0.61,0.36,1)';
  const riseIn = (seconds) => ({
    name: 'sppKbRise',
    seconds,
    keyframes:
      '@keyframes sppKbRise{' +
      '0%{opacity:0; transform:translate3d(0,46px,0) scale(0.86); animation-timing-function:' + EASE + '}' +
      '13%{opacity:1; transform:translate3d(0,0,0) scale(0.9); animation-timing-function:linear}' +
      '100%{opacity:1; transform:translate3d(0,0,0) scale(1)}}',
  });
  // Slide across + pull back (scene 2) — the opposite move on both axes, so the
  // same photograph reads as a new shot after the cut.
  const drawBack = (seconds) => ({
    name: 'sppKbDraw',
    seconds,
    keyframes:
      '@keyframes sppKbDraw{' +
      '0%{opacity:0; transform:translate3d(-54px,0,0) scale(0.86); animation-timing-function:' + EASE + '}' +
      '12%{opacity:1; transform:translate3d(-10px,0,0) scale(0.94); animation-timing-function:linear}' +
      '100%{opacity:1; transform:translate3d(16px,0,0) scale(0.88)}}',
  });

  // Photo boxes are inset from their plate by MAT on every side. MAT is larger
  // than the plates' 48px corner radius on purpose: a square product photo (the
  // most common e-commerce crop) fills its box in BOTH axes, so a smaller inset
  // would push the photo's square corners under the plate's rounded ones and
  // clip them. Insetting past the radius makes every aspect ratio safe.
  const MAT = 56;

  // Chips, badges and buttons: the pill itself is the ELEMENT (background +
  // radius on `style`), the inner div only carries padding and type. That way
  // the declared colours are the ones actually painted — the layout linter can
  // check the real label-on-accent contrast instead of guessing at the scene
  // background behind it.
  const chipStyle = (bg, fg) => ({ fontFamily: uiFont, color: fg, backgroundColor: bg, borderRadius: '999px' });

  // ---- timing -------------------------------------------------------------
  // A scene transition overlaps its two scenes, so every non-last scene is
  // padded by its transition length and the on-screen time stays as designed.
  const T1 = 0.6;
  const T2 = 0.55;
  const hookDur = round2(4.5 + T1);
  const offerDur = round2(5.2 + T2);
  const ctaDur = 4.6;
  const totalSeconds = round2(hookDur + offerDur + ctaDur - T1 - T2);

  // =========================================================================
  // Scene 1 — hook: kicker, product on a cream plate, product name
  // =========================================================================
  const hookSvg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs>" +
    "<radialGradient id='sppGlow' cx='0.5' cy='0.4' r='0.75'>" +
    "<stop offset='0' stop-color='" + accent + "' stop-opacity='0.42'/>" +
    "<stop offset='0.52' stop-color='" + accent + "' stop-opacity='0.12'/>" +
    "<stop offset='1' stop-color='" + ink + "' stop-opacity='0'/>" +
    '</radialGradient></defs>' +
    "<rect width='1080' height='1920' fill='" + ink + "'/>" +
    "<rect width='1080' height='1920' fill='url(#sppGlow)'/>" +
    "<rect x='54' y='54' width='972' height='1812' rx='44' fill='none' stroke='" + rgba(CREAM, 0.18, CREAM_RGB) + "' stroke-width='1.5'/>" +
