    "<circle cx='930' cy='1786' r='6' fill='" + rgba(CREAM, 0.4, CREAM_RGB) + "'/>" +
    '</svg>';

  const titleTopY = 1478;
  const titleBlockH = Math.round(titleFit.lines * titleFit.size * 1.08);
  const hookVisuals = [
    { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: hookDur, svg: hookSvg },
    // cream plate: x 120..960, y 440..1400 -> centre (540, 920)
    photoLayer(heroImage, 540, 920, 840 - 2 * MAT, 960 - 2 * MAT, 1, CREAM, rgba(ink, 0.16), riseIn(hookDur)),
    {
      type: 'TEXT', x: 540, y: 150, anchor: 'top-center', track: 2, enterBegin: 0.1, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: hookDur,
      style: { fontFamily: uiFont, color: CREAM, borderRadius: '999px', border: '1.5px solid ' + rgba(CREAM, 0.55, CREAM_RGB) },
      html: "<div style='display:inline-block; padding:15px 40px; font-size:25px; font-weight:700; letter-spacing:7px;'>" + esc(brandName.toUpperCase()) + '</div>',
    },
    {
      type: 'TEXT', x: 90, y: 1408, anchor: 'top-left', track: 3, enterBegin: 0.45, enterEnd: 0.85, enterAnimation: 'smoothright', exitEnd: hookDur,
      style: { fontFamily: uiFont, color: onAccent, backgroundColor: accent, borderRadius: '8px' },
      html: "<div style='display:inline-block; padding:12px 26px; font-size:25px; font-weight:800; letter-spacing:6px;'>" + esc(kicker) + '</div>',
    },
    {
      type: 'TEXT', x: 90, y: titleTopY, width: 900, anchor: 'top-left', track: 4, enterBegin: 0.7, enterEnd: 1.2, enterAnimation: reveal(titleFit), exitEnd: hookDur,
      style: { fontFamily: titleFont, color: CREAM },
      html: "<div style='color:" + CREAM + '; font-size:' + titleFit.size + "px; line-height:1.08; font-weight:700; letter-spacing:-1px;'>" + esc(titleFit.text) + '</div>',
    },
    {
      type: 'TEXT', x: 90, y: Math.max(1770, titleTopY + titleBlockH + 40), anchor: 'top-left', track: 5, enterBegin: 1.1, enterEnd: 1.45, enterAnimation: 'fade', exitEnd: hookDur,
      style: { fontFamily: uiFont, color: rgba(CREAM, 0.62, CREAM_RGB) },
      html: "<div style='color:" + rgba(CREAM, 0.62, CREAM_RGB) + "; font-size:25px; font-weight:600; letter-spacing:4px;'>" + esc((storeDomain || brandHandle || brandName).toUpperCase()) + '</div>',
    },
  ];

  // =========================================================================
  // Scene 2 — offer: second angle, tagline, price + saving
  // =========================================================================
  const offerSvg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs>" +
    "<linearGradient id='sppCard' x1='0' y1='0' x2='0' y2='1'>" +
    "<stop offset='0' stop-color='" + lighten(ink, 16) + "'/><stop offset='1' stop-color='" + ink + "'/>" +
    '</linearGradient></defs>' +
    "<rect width='1080' height='1920' fill='" + CREAM + "'/>" +
    "<circle cx='980' cy='190' r='250' fill='" + rgba(accent, 0.12) + "'/>" +
    "<circle cx='120' cy='1780' r='170' fill='" + rgba(accent, 0.1) + "'/>" +
    "<rect x='110' y='232' width='860' height='886' rx='48' fill='url(#sppCard)'/>" +
    "<path d='M110 1198 H970' stroke='" + rgba(ink, 0.16) + "' stroke-width='2'/>" +
    "<rect x='110' y='1198' width='150' height='5' rx='2.5' fill='" + accent + "'/>" +
    "<circle cx='930' cy='1802' r='6' fill='" + rgba(ink, 0.35) + "'/>" +
    "<circle cx='894' cy='1802' r='6' fill='" + rgba(ink, 0.35) + "'/>" +
    "<circle cx='858' cy='1802' r='6' fill='" + accent + "'/>" +
    '</svg>';

  const taglineTopY = 1256;
  const taglineBlockH = tagline ? Math.round(taglineFit.lines * taglineFit.size * 1.34) : 0;
  const priceY = tagline ? Math.max(1452, taglineTopY + taglineBlockH + 46) : 1330;

  // Inline spans (not flex) so the element is measured from its content and the
  // struck compare-at price sits on the same baseline as the live price.
  const priceHtml = (() => {
    let h = "<div style='white-space:nowrap;'>";
    h += "<span style='color:" + ink + "; font-size:96px; line-height:1.1; font-weight:800; letter-spacing:-2px;'>" + esc(priceText || '—') + '</span>';
    if (compareText) {
      h += "<span style='margin-left:28px; color:" + rgba(ink, 0.45) + "; font-size:46px; font-weight:600; text-decoration:line-through;'>" + esc(compareText) + '</span>';
    }
    return h + '</div>';
  })();

  const offerVisuals = [
    { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: offerDur, svg: offerSvg },
    // dark card: x 110..970, y 232..1118 -> centre (540, 675)
    photoLayer(offerImage, 540, 675, 860 - 2 * MAT, 886 - 2 * MAT, 1, ink, rgba(CREAM, 0.2, CREAM_RGB), drawBack(offerDur)),
    // NOTE: no brand wordmark at the top of this scene. The hook already sets
    // one at y=150; repeating the same string 2 px away meant the wipe between
    // the two scenes printed it twice at two offsets. The store signature lives
    // in the footer of this scene instead.
    {
      type: 'TEXT', x: 90, y: priceY, anchor: 'top-left', track: 5, enterBegin: 0.95, enterEnd: 1.35, enterAnimation: 'smoothup', exitEnd: offerDur,
      style: { fontFamily: uiFont, color: ink },
      html: priceHtml,
    },
    {
      // The hook footer carries the store signature; this one carries the brand
      // name, so the two scenes never print the same string in the same place
      // through the wipe that joins them.
      type: 'TEXT', x: 90, y: 1790, anchor: 'top-left', track: 7, enterBegin: 1.35, enterEnd: 1.7, enterAnimation: 'fade', exitEnd: offerDur,
      style: { fontFamily: uiFont, color: rgba(ink, 0.55) },
      html: "<div style='color:" + rgba(ink, 0.55) + "; font-size:25px; font-weight:600; letter-spacing:4px;'>" + esc(brandName.toUpperCase()) + '</div>',
    },
  ];
  if (tagline) {
    offerVisuals.push({
      type: 'TEXT', x: 90, y: taglineTopY, width: 900, anchor: 'top-left', track: 4, enterBegin: 0.6, enterEnd: 1.05, enterAnimation: reveal(taglineFit), exitEnd: offerDur,
      style: { fontFamily: titleFont, color: ink },
      html: "<div style='color:" + ink + '; font-size:' + taglineFit.size + "px; line-height:1.34; font-weight:600; font-style:italic;'>" + esc(taglineFit.text) + '</div>',
    });
  }
  if (showSave) {
    offerVisuals.push({
      type: 'TEXT', x: 852, y: 268, anchor: 'center-center', angle: -8, track: 3, enterBegin: 0.75, enterEnd: 1.15, enterAnimation: 'circleopen', exitEnd: offerDur,
      style: chipStyle(accent, onAccent),
      html: "<div style='display:inline-block; padding:20px 34px; text-align:center; font-size:40px; line-height:1; font-weight:800; letter-spacing:-1px;'>SAVE " + savePct + '%</div>',
    });
  }

  // =========================================================================
  // Scene 3 — call to action
  // =========================================================================
  const monogram = (brandName.replace(/[^A-Za-z0-9]/g, '')[0] || 'S').toUpperCase();

  // The end card is a single centred stack, so its height changes with the
  // product name (one or two lines) and with whether there is a price to show.
  // Measure the stack first, then centre it — otherwise a short name leaves a
  // third of the frame empty under the button.
  const ctaTitleFit = fitBlock(title, [58, 50, 44, 38], 860, 0.52, 2);
  const ctaTitleH = Math.round(ctaTitleFit.lines * ctaTitleFit.size * 1.12);
  const RING_R = 178;
  const GAP_RING_BRAND = 118;
  const BRAND_H = 34;
  const GAP_BRAND_TITLE = 48;
  const PRICE_H = priceText ? 56 : 0;
  const GAP_TITLE_PRICE = priceText ? 34 : 0;
  const GAP_PRICE_PILL = 62;
  const PILL_H = 100;
  const GAP_PILL_DOMAIN = 56;
  const DOMAIN_H = 36;
  const stackH = 2 * RING_R + GAP_RING_BRAND + BRAND_H + GAP_BRAND_TITLE + ctaTitleH + GAP_TITLE_PRICE + PRICE_H + GAP_PRICE_PILL + PILL_H + GAP_PILL_DOMAIN + DOMAIN_H;
  const stackTop = Math.max(180, Math.round((1920 - stackH) / 2));
  const ringCy = stackTop + RING_R;
  const brandY = stackTop + 2 * RING_R + GAP_RING_BRAND;
  const ctaTitleY = brandY + BRAND_H + GAP_BRAND_TITLE;
  const ctaPriceY = ctaTitleY + ctaTitleH + GAP_TITLE_PRICE;
  const pillY = ctaPriceY + PRICE_H + GAP_PRICE_PILL;
  const domainY = pillY + PILL_H + GAP_PILL_DOMAIN;

  const ctaSvg =
    "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs>" +
    "<radialGradient id='sppCta' cx='0.5' cy='0.34' r='0.85'>" +
    "<stop offset='0' stop-color='" + lighten(ink, 26) + "'/><stop offset='1' stop-color='" + ink + "'/>" +
    '</radialGradient></defs>' +
    "<rect width='1080' height='1920' fill='url(#sppCta)'/>" +
    "<rect x='54' y='54' width='972' height='1812' rx='44' fill='none' stroke='" + rgba(accent, 0.4) + "' stroke-width='1.5'/>" +
    "<circle cx='540' cy='" + ringCy + "' r='" + RING_R + "' fill='none' stroke='" + rgba(accent, 0.45) + "' stroke-width='2'/>" +
    "<circle cx='540' cy='" + ringCy + "' r='148' fill='" + accent + "'/>" +
    "<path d='M112 1606 L112 1712 L218 1712' fill='none' stroke='" + rgba(CREAM, 0.5, CREAM_RGB) + "' stroke-width='8' stroke-linecap='square'/>" +
    "<path d='M968 320 L968 214 L862 214' fill='none' stroke='" + rgba(CREAM, 0.5, CREAM_RGB) + "' stroke-width='8' stroke-linecap='square'/>" +
    '</svg>';

  const ctaVisuals = [
    { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: ctaDur, svg: ctaSvg },
    {
      type: 'TEXT', x: 540, y: ringCy, anchor: 'center-center', track: 1, enterBegin: 0.15, enterEnd: 0.55, enterAnimation: 'fade', exitEnd: ctaDur,
      style: { fontFamily: titleFont, color: onAccent, backgroundColor: accent, borderRadius: '999px' },
      html: "<div style='text-align:center; padding:0 30px; font-size:126px; line-height:1.1; font-weight:700;'>" + esc(monogram) + '</div>',
    },
    {
      type: 'TEXT', x: 540, y: brandY, anchor: 'top-center', track: 2, enterBegin: 0.35, enterEnd: 0.7, enterAnimation: 'fade', exitEnd: ctaDur,
      style: { fontFamily: uiFont, color: rgba(CREAM, 0.7, CREAM_RGB) },
      html: "<div style='text-align:center; color:" + rgba(CREAM, 0.7, CREAM_RGB) + "; font-size:26px; font-weight:700; letter-spacing:9px;'>" + esc(brandName.toUpperCase()) + '</div>',
    },
    {
      type: 'TEXT', x: 540, y: ctaTitleY, width: 860, anchor: 'top-center', track: 3, enterBegin: 0.55, enterEnd: 0.95, enterAnimation: reveal(ctaTitleFit), exitEnd: ctaDur,
      style: { fontFamily: titleFont, color: CREAM },
      html: "<div style='text-align:center; color:" + CREAM + '; font-size:' + ctaTitleFit.size + "px; line-height:1.12; font-weight:700;'>" + esc(ctaTitleFit.text) + '</div>',
    },
    {
      type: 'TEXT', x: 540, y: pillY, anchor: 'top-center', track: 5, enterBegin: 1.0, enterEnd: 1.45, enterAnimation: 'circleopen', exitEnd: ctaDur,
      style: chipStyle(accent, onAccent),
      html: "<div style='display:inline-block; padding:28px 66px; font-size:40px; font-weight:800;'>" + esc(shopNowText) + '</div>',
    },
    {
      type: 'TEXT', x: 540, y: domainY, anchor: 'top-center', track: 6, enterBegin: 1.35, enterEnd: 1.7, enterAnimation: 'fade', exitEnd: ctaDur,
      style: { fontFamily: uiFont, color: rgba(CREAM, 0.6, CREAM_RGB) },
      html: "<div style='text-align:center; color:" + rgba(CREAM, 0.6, CREAM_RGB) + "; font-size:28px; font-weight:600; letter-spacing:3px;'>" + esc(storeDomain || brandHandle || '') + '</div>',
    },
  ];
  if (priceText) {
    ctaVisuals.push({
      type: 'TEXT', x: 540, y: ctaPriceY, anchor: 'top-center', track: 4, enterBegin: 0.8, enterEnd: 1.2, enterAnimation: 'smoothup', exitEnd: ctaDur,
      style: { fontFamily: uiFont, color: readableAccent },
      html: "<div style='text-align:center; color:" + readableAccent + "; font-size:44px; font-weight:800; letter-spacing:1px;'>" + esc(priceText) + (compareText ? "<span style='margin-left:18px; color:" + rgba(CREAM, 0.45, CREAM_RGB) + "; font-size:30px; font-weight:600; text-decoration:line-through;'>" + esc(compareText) + '</span>' : '') + '</div>',
    });
  }

  const scenes = [
    { id: 'hook', duration: hookDur, backgroundColor: ink, transition: 'smoothup', transitionId: 'offer', transitionDuration: T1, visuals: hookVisuals },
    { id: 'offer', duration: offerDur, backgroundColor: CREAM, transition: 'fade', transitionId: 'cta', transitionDuration: T2, visuals: offerVisuals },
    { id: 'cta', duration: ctaDur, backgroundColor: ink, visuals: ctaVisuals },
  ];

  // The render API only allows letters, digits, spaces, _ and - in `name`.
  const safeName = ('new-arrival-' + title)
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);

  const payload = {
    name: safeName || 'new-arrival',
    resolution: 'instagram-reel',
    frameRate: 30,
    backgroundColor: ink,
    outputFormat: 'mp4',
    scenes,
  };
  // NOTE: no `track` on audios — the render API rejects audios[].track.
  if (musicOk) payload.audios = [{ src: musicUrl, volume: Number(cfg.musicVolume) > 0 ? Number(cfg.musicVolume) : 0.16 }];

  return {
    payload,
    meta: {
      title,
      titleChars: title.length,
      titleSize: titleFit.size,
      titleLines: titleFit.lines,
      titleShown: titleFit.text,
      titleTruncated: titleFit.truncated,
      ctaTitleShown: ctaTitleFit.text,
      ctaTitleTruncated: ctaTitleFit.truncated,
      tagline,
      taglineSize: taglineFit.size,
      taglineLines: taglineFit.lines,
      taglineTruncated: taglineFit.truncated,
      priceText,
      compareText,
      savePct: showSave ? savePct : 0,
      imageCount: images.length,
      imageReused,
      heroImage,
      offerImage,
      storeDomain,
      monogram,
      musicIncluded: musicOk,
      musicSkipped,
      musicUrl,
      musicBytes,
      totalSeconds,
      source: clean(product && product.source) || 'sheet',
      rowNumber: product && product.rowNumber,
      productId: (product && product.productId) || null,
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const productItem = $('New product?').first().json;
const probe = $input.first().json || {};
const built = buildProject(config, productItem, probe);
return [{ json: built }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug - surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// exact video, then set dryRun to false in Config to go live. Neither the sheet
// row nor the Shopify last-seen marker is touched, so the next real run picks
// the same product.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    source: d.meta.source,
    product: d.meta.title,
    tagline: d.meta.tagline,
    price: d.meta.priceText,
    compareAtPrice: d.meta.compareText || null,
    savePercent: d.meta.savePct || null,
    photosUsed: d.meta.imageCount,
    secondAngle: d.meta.imageReused === false,
    sheetRow: d.meta.rowNumber,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalSeconds,
    warnings: d.warnings,
    sheetUpdated: false,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render for real.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for a live run. In sheet mode the row is already marked done by
// this point. In Shopify mode the announced product id is remembered HERE -
// only after a successful render - so a failed render retries the same product
// on the next poll instead of silently skipping it.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

const source = String(cfg.source || 'sheet').toLowerCase();
if (source === 'shopify' && build.meta.productId) {
  const staticData = $getWorkflowStaticData('global');
  staticData.lastProductId = String(build.meta.productId);
}

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
    source,
    product: build.meta.title,
    price: build.meta.priceText,
    compareAtPrice: build.meta.compareText || null,
    savePercent: build.meta.savePct || null,
    photosUsed: build.meta.imageCount,
    secondAngle: build.meta.imageReused === false,
    music: build.meta.musicIncluded ? 'on' : ('off - ' + (build.meta.musicSkipped || 'no musicUrl')),
    videoSeconds: build.meta.totalSeconds,
    creditsCharged: build.creditsRequired,
    sheetRow: build.meta.rowNumber,
    sheetStatus: source === 'sheet' ? cfg.statusDoneValue : null,
    productId: build.meta.productId,
    storeDomain: build.meta.storeDomain,
  },
}];
